#!/usr/bin/env node
/**
 * build-articles.js
 * Generates individual HTML pages for each article from index.html
 * Also regenerates sitemap.xml
 *
 * Usage: node build-articles.js
 * Zero dependencies — uses only Node.js built-ins.
 */

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const ARTICLES_DIR = path.join(ROOT, 'articles');
const INDEX_PATH = path.join(ROOT, 'index.html');
const MAIN_JS_PATH = path.join(ROOT, 'js', 'main.src.js');
const SITEMAP_PATH = path.join(ROOT, 'sitemap.xml');
const BASE_URL = 'https://elainklinikkasaari.fi';
// Footer "Services" quick link targets the services hub, so every page links to it (the EN hub fell out of Google's index while only the hubs linked to each other).
const SERVICES_HUB_URL = { fi: '/palvelut/', sv: '/sv/tjanster/', en: '/en/services/' };
const PRICES_URLS = { fi: '/hinnasto/', sv: '/sv/prislista/', en: '/en/pricelist/' };
const SHOP_URLS = { fi: 'https://kauppa.elainklinikkasaari.fi/', sv: 'https://kauppa.elainklinikkasaari.fi/?lang=sv', en: 'https://kauppa.elainklinikkasaari.fi/' };
const SHOP_LABELS = { fi: 'Verkkokauppa', sv: 'Webbutik', en: 'Online shop' };
const SHOP_CART_SVG = '<svg class="nav-shop-ico" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="8" cy="21" r="1"/><circle cx="19" cy="21" r="1"/><path d="M2.05 2.05h2l2.66 12.42a2 2 0 0 0 2 1.58h9.78a2 2 0 0 0 1.95-1.57l1.65-7.43H5.12"/></svg>';

// Cache-busting suffixes for /js/main.js and /css/style.css, e.g. "?v=20260803c".
// The homepage is hand-maintained, so index.html is the single source of truth:
// bump the ?v= there and every generated page follows on the next build. Without
// this, generated pages request the unversioned URL — which both serves stale
// CSS/JS after a deploy and caches main.js twice under two different keys.
// The two files are versioned independently (CSS-only deploys bump only style.css).
function assetVersion(file, pattern) {
  const m = fs.readFileSync(INDEX_PATH, 'utf8').match(pattern);
  if (!m) {
    console.warn(`  WARN: no ?v= found on ${file} in index.html — generated pages will be unversioned`);
    return '';
  }
  return m[1];
}
const ASSET_VERSION = assetVersion('main.js', /js\/main\.js\?v=([A-Za-z0-9._-]+)/);
const ASSET_Q = ASSET_VERSION ? `?v=${ASSET_VERSION}` : '';
const CSS_VERSION = assetVersion('style.css', /css\/style\.css\?v=([A-Za-z0-9._-]+)/);
const CSS_Q = CSS_VERSION ? `?v=${CSS_VERSION}` : '';

// js/main.js is built from js/main.src.js by build-main-js.js, which drops the
// `article.*` translation keys (the article bodies — they live in the static HTML).
// A bundle that still carries them was built by hand with a bare `npx esbuild`;
// warn so it is rebuilt before deploy instead of shipping 680 KB of dead weight.
(() => {
  const mainJs = path.join(ROOT, 'js', 'main.js');
  if (fs.existsSync(mainJs) && fs.readFileSync(mainJs, 'utf8').includes('"article.')) {
    console.warn('  WARN: js/main.js still contains article.* translations — run `node build-main-js.js`');
  }
})();

// '27.9.2026' → '2026-09-27' for <time datetime="…">.
function isoDate(dmy) {
  const m = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(dmy || '');
  return m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : '';
}

// Share card for a clinic photo: /images/og/<path-under-images-without-ext, "/" → "__">.jpg
// (1200×630, rendered by build-share-cards.py — run it after this build when figures change).
function shareCardUrl(src) {
  return `${BASE_URL}/images/og/${src.replace(/^\/images\//, '').replace(/\.[a-z0-9]+$/i, '').replace(/\//g, '__')}.jpg`;
}

// Returns the localized slug for an article in the given language.
// Falls back to the Finnish slug if no localized slug is defined.
function articleSlug(article, lang) {
  if (lang === 'sv') return article.slugSv || article.slug;
  if (lang === 'en') return article.slugEn || article.slug;
  return article.slug;
}

// Generates a client-side redirect stub (meta refresh + canonical).
// Used for old legacy SV/EN article paths to point at new localized slugs.
// GitHub Pages has no native 301 support, so this is the best available option.
function generateRedirectStub(targetUrl) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Redirecting…</title>
<link rel="canonical" href="${targetUrl}">
<meta name="robots" content="noindex,follow">
<meta http-equiv="refresh" content="0; url=${targetUrl}">
<script>window.location.replace(${JSON.stringify(targetUrl)});</script>
</head>
<body>
<p>This page has moved. Redirecting to <a href="${targetUrl}">${targetUrl}</a>…</p>
</body>
</html>`;
}

// Shared cookie consent banner — emitted on every page so first-time visitors
// landing on any URL can grant/deny consent. Loader for Clarity runs only
// after consent is accepted (mirrors GA4 consent-mode v2 flow).
// Inline scripts are minified with esbuild at build time (deterministic; cached per snippet).
const { execFileSync } = require('child_process');
const minifyCache = new Map();
function minifyJs(code) {
  if (minifyCache.has(code)) return minifyCache.get(code);
  let out;
  try {
    out = execFileSync('npx', ['--yes', 'esbuild', '--minify', '--target=es2017'], {
      input: code, encoding: 'utf8', stdio: ['pipe', 'pipe', 'inherit'],
    }).trim();
  } catch (e) {
    console.warn('  WARN: esbuild unavailable — inline script left unminified');
    out = code;
  }
  minifyCache.set(code, out);
  return out;
}

// The cookie banner, the tag loaders and the consent state all live in js/consent.js since
// 08-11-2026 (pages load it in <head>, before their inline gtag/fbq calls). Kept as a no-op so the
// page templates below need no change.
function renderCookieBanner() { return ''; }
// Privacy policy per language (tools/consent/build_privacy.py builds the pages).
const PRIVACY_HREF = { fi: '/tietosuoja/', sv: '/sv/dataskydd/', en: '/en/privacy/' };
const PRIVACY_LABEL = {"fi": "Tietosuojaseloste ja yritystiedot", "sv": "Dataskyddsbeskrivning och företagsuppgifter", "en": "Privacy policy and company information"};

