function generateReviewsPage(lang) {
  const i18n = {
    fi: {
      htmlLang: 'fi', ogLocale: 'fi_FI',
      pageTitle: 'Asiakkaiden arvostelut | Eläinklinikka Saari',
      h1: 'Asiakkaiden arvostelut',
      metaDesc: 'Eläinklinikka Saari Googlessa: keskiarvo 4,6 / 5 ja 359 arvostelua. Lue mitä asiakkaamme sanovat eläinlääkäreistämme ja palvelustamme Vaasassa.',
      brandName: 'Eläinklinikka Saari',
      reviewsOnGoogle: 'arvostelua Googlessa',
      reviewsOnFacebook: '+ 73 suositusta Facebookissa (98 % suosittelee)',
      featuredNote: "Tässä on 29 arvostelua, jotka olemme valinneet Googlesta ja Facebookista. Emme tarkista, onko jokainen kirjoittaja ollut asiakkaamme. Voit lukea Googlesta kaikki Google-arvostelumme, hyvät ja huonot.",
      ctaHeading: 'Onko sinulla kokemus jaettavana?',
      ctaText: 'Lue kaikki arvostelumme Googlessa tai kirjoita oma — autat muita lemmikinomistajia löytämään luotettavan klinikan.',
      ctaReadAll: 'Lue kaikki Googlessa',
      backToHome: '← Takaisin etusivulle',
      skipLink: 'Siirry sisältöön',
      footnote: 'Arvostelut on koottu Google-asiakasarvosteluista ja näytetään tällä sivulla sellaisina kuin asiakkaamme ovat ne kirjoittaneet. Klikkaa Google-linkkiä yltä nähdäksesi kaikki ja jättääksesi oman arviosi.',
    },
    sv: {
      htmlLang: 'sv', ogLocale: 'sv_FI',
      pageTitle: 'Kundernas omdömen | Djurklinik Saari',
      h1: 'Kundernas omdömen',
      metaDesc: 'Djurklinik Saari på Google: genomsnitt 4,6 / 5 och 359 omdömen. Läs vad våra kunder säger om våra veterinärer och vår service i Vasa.',
      brandName: 'Djurklinik Saari',
      reviewsOnGoogle: 'omdömen på Google',
      reviewsOnFacebook: '+ 73 rekommendationer på Facebook (98 % rekommenderar)',
      featuredNote: "Här är 29 omdömen som vi har valt ut från Google och Facebook. Vi kontrollerar inte om var och en som har skrivit ett omdöme har varit vår kund. Alla våra Google-omdömen, både bra och dåliga, kan du läsa på Google.",
      ctaHeading: 'Har du en erfarenhet att dela?',
      ctaText: 'Läs alla våra omdömen på Google eller skriv ett eget — hjälper andra djurägare att hitta en pålitlig klinik.',
      ctaReadAll: 'Läs alla på Google',
      backToHome: '← Tillbaka till startsidan',
      skipLink: 'Hoppa till innehållet',
      footnote: 'Omdömena är hämtade från Googles kundomdömen och visas på denna sida i den form våra kunder skrivit dem. Klicka på Google-länken ovan för att se alla och lämna ditt eget.',
    },
    en: {
      htmlLang: 'en', ogLocale: 'en_GB',
      pageTitle: 'Customer reviews | Saari Animal Clinic',
      h1: 'Customer reviews',
      metaDesc: 'Saari Animal Clinic on Google: average 4.6 / 5 from 359 reviews. Read what our customers say about our veterinarians and service in Vaasa.',
      brandName: 'Saari Animal Clinic',
      reviewsOnGoogle: 'reviews on Google',
      reviewsOnFacebook: '+ 73 recommendations on Facebook (98% recommend)',
      featuredNote: "These are 29 reviews we picked from Google and Facebook. We do not check whether each writer has been our client. You can read all our Google reviews, good and bad, on Google.",
      ctaHeading: 'Have an experience to share?',
      ctaText: 'Read all our reviews on Google or write your own — you help other pet owners find a trustworthy clinic.',
      ctaReadAll: 'Read all on Google',
      backToHome: '← Back to homepage',
      skipLink: 'Skip to content',
      footnote: 'Reviews are taken from Google Customer Reviews and shown on this page exactly as our customers wrote them. Click the Google link above to see all and leave your own.',
    },
  }[lang] || null;
  if (!i18n) throw new Error(`Unknown lang: ${lang}`);

  // Real Google Business Profile totals (verified from GBP dashboard)
  const GOOGLE_TOTAL_REVIEWS = 359;
  const GOOGLE_AVG_RATING = 4.6;

  const urls = {
    fi: `${BASE_URL}/arvostelut/`,
    sv: `${BASE_URL}/sv/omdomen/`,
    en: `${BASE_URL}/en/reviews/`,
  };
  const canonicalUrl = urls[lang];
  const homeUrl = lang === 'fi' ? '/' : `/${lang}/`;
  // Asset prefix: /arvostelut/ is one level deep (FI); /sv/omdomen/ and /en/reviews/ are two levels deep
  const assetPrefix = lang === 'fi' ? '../' : '../../';
  // Google Business Profile reviews — direct deep-link to the reviews tab for Eläinklinikka Saari
  const googleReviewsUrl = 'https://www.google.com/search?q=El%C3%A4inklinikka+Saari+Oy+Reviews&rflfq=1&num=20&stick=H4sIAAAAAAAAAONgkxI2tzQzMDM1BgJDA0sTYwsjY-MNjIyvGOVdcw4vyczLzsnMy8zOTlQITkwsylTwr1QISi3LTC0vXsRKSAUAybtVjF4AAAA&tbm=lcl&rldimm=7960653333109438233#lkt=LocalPoiReviews';

  // Star characters
  const star = '★';
  const stars5 = star.repeat(5);

  // Avatar palette — pick a colour per review based on first-letter hash for visual variety
  const AVATAR_PALETTE = ['#E58DB4', '#7BA7BC', '#A082C9', '#E3A857', '#5FA88A', '#D08CA8', '#6B8BB5', '#C77B7B'];
  const initialOf = (name) => {
    const m = (name || '').trim().match(/[A-Za-zÀ-ɏА-я]/);
    return m ? m[0].toUpperCase() : '?';
  };
  const avatarColourFor = (name) => {
    let h = 0;
    for (const ch of name) h = (h * 31 + ch.charCodeAt(0)) | 0;
    return AVATAR_PALETTE[Math.abs(h) % AVATAR_PALETTE.length];
  };

  // Render review cards
  const reviewCards = REVIEWS.map((r) => {
    const yearLabel = r.date.slice(0, 4);
    const escapedBody = escapeHtml(r.body);
    const escapedAuthor = escapeHtml(r.author);
    const dateAttr = r.date;
    const initial = initialOf(r.author);
    const colour = avatarColourFor(r.author);
    return `        <article class="review-card">
          <div class="review-card-header">
            <div class="review-card-avatar" style="background:${colour};" aria-hidden="true">${initial}</div>
            <div class="review-card-identity">
              <span class="review-card-author">${escapedAuthor}</span>
              <span class="review-card-source"><span class="review-card-source-icon review-card-source-icon--${r.source.toLowerCase()}" aria-hidden="true"></span>${escapeHtml(r.source)}</span>
            </div>
          </div>
          <div class="review-card-stars-row">
            <span class="review-card-stars" aria-label="${r.rating} / 5">${star.repeat(r.rating)}</span>
            <span class="review-card-date"><time datetime="${dateAttr}">${yearLabel}</time></span>
          </div>
          <div class="review-card-body">${escapedBody}</div>
        </article>`;
  }).join('\n');

  // Build JSON-LD structured data (Review array + AggregateRating embedded in VeterinaryCare)
  // AggregateRating reflects the FULL Google Business Profile (359 reviews @ 4.6 avg, checked on Google Maps 20-11-2026);
  // individual Review entries are the 14 we're displaying on this page.
  const featuredCount = REVIEWS.length;
  // Reviews are nested under VeterinaryCare.review — Google rejects a
  // nested itemReviewed there (directional conflict, GSC 5/23/26).
  const reviewJsonLd = REVIEWS.map((r) => ({
    '@type': 'Review',
    author: { '@type': 'Person', name: r.author },
    reviewBody: r.body,
    reviewRating: { '@type': 'Rating', ratingValue: r.rating, bestRating: 5, worstRating: 1 },
    datePublished: r.date,
    publisher: { '@type': 'Organization', name: r.source },
  }));

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'WebPage',
    name: i18n.pageTitle,
    description: i18n.metaDesc,
    url: canonicalUrl,
    inLanguage: lang,
    isPartOf: { '@type': 'WebSite', '@id': `${BASE_URL}/#website`, name: i18n.brandName, url: BASE_URL },
    about: {
      '@type': ['VeterinaryCare', 'LocalBusiness'],
      '@id': `${BASE_URL}/#clinic`,
      name: i18n.brandName,
      url: BASE_URL,
      telephone: '+358-6-321-7300',
      address: {
        '@type': 'PostalAddress',
        streetAddress: 'Gerbyntie 18',
        postalCode: '65230',
        addressLocality: 'Vaasa',
        addressCountry: 'FI',
      },
      aggregateRating: {
        '@type': 'AggregateRating',
        ratingValue: GOOGLE_AVG_RATING,
        reviewCount: GOOGLE_TOTAL_REVIEWS,
        bestRating: 5,
        worstRating: 1,
      },
      review: reviewJsonLd,
    },
  };

  // Star bar with partial fill — accurately shows 4.6/5
  const fillPct = (GOOGLE_AVG_RATING / 5) * 100;
  const starBarHtml = `<span class="reviews-aggregate-starbar" aria-label="${GOOGLE_AVG_RATING} / 5"><span class="reviews-aggregate-starbar-bg">${stars5}</span><span class="reviews-aggregate-starbar-fg" style="width:${fillPct.toFixed(2)}%;">${stars5}</span></span>`;
  // Locale-formatted rating: 4,6 for FI/SV, 4.6 for EN
  const ratingDisplay = (lang === 'en') ? GOOGLE_AVG_RATING.toFixed(1) : GOOGLE_AVG_RATING.toFixed(1).replace('.', ',');

  return `<!DOCTYPE html>
<html lang="${i18n.htmlLang}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="robots" content="index,follow">
  <meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self' 'unsafe-inline' https://news.google.com https://www.googletagmanager.com https://www.googleadservices.com https://www.google.com https://googleads.g.doubleclick.net https://connect.facebook.net https://*.facebook.net  https://www.clarity.ms https://*.clarity.ms; style-src 'self' 'unsafe-inline'; img-src 'self' data: https://pagead2.googlesyndication.com https://www.googleadservices.com https://www.google.com https://www.google.fi https://googleads.g.doubleclick.net https://www.googletagmanager.com https://www.facebook.com https://*.facebook.com; font-src 'self'; connect-src 'self' https://pagead2.googlesyndication.com https://stats.g.doubleclick.net https://www.googleadservices.com https://googleads.g.doubleclick.net https://ad.doubleclick.net https://www.google.com https://www.google-analytics.com https://*.google-analytics.com https://www.googletagmanager.com https://analytics.google.com https://*.analytics.google.com https://www.facebook.com https://*.facebook.com https://*.facebook.net https://*.clarity.ms; frame-src https://www.google.com https://td.doubleclick.net https://news.google.com">
  <title>${escapeHtml(i18n.pageTitle)}</title>

  <script src="/js/consent.js?v=20261109b"></script>
  <script>
    window.dataLayer = window.dataLayer || [];
    function gtag(){dataLayer.push(arguments);}
    gtag('consent', 'default', {
      'analytics_storage': 'denied',
      'ad_storage': 'denied',
      'ad_user_data': 'denied',
      'ad_personalization': 'denied'
    });
    gtag('js', new Date());
    gtag('config', 'G-WKS3P1RFC2');
  </script>
  <!-- Google Ads: Click to call / booking conversion -->
  <script>
  function gtag_report_conversion(url) {
    var callback = function () {
      if (typeof(url) != 'undefined') {
        window.location = url;
      }
    };
    gtag('event', 'conversion', {
      'send_to': 'AW-816483191/jzTzCJrAgJwcEPeWqoUD',
      'value': 1.0,
      'currency': 'EUR',
      'transport_type': 'beacon', 'event_callback': callback
    });
    return false;
  }
  </script>

  <meta name="description" content="${escapeAttr(i18n.metaDesc)}">
  <link rel="canonical" href="${canonicalUrl}">
  <link rel="alternate" hreflang="fi" href="${urls.fi}">
  <link rel="alternate" hreflang="sv" href="${urls.sv}">
  <link rel="alternate" hreflang="en" href="${urls.en}">
  <link rel="alternate" hreflang="x-default" href="${urls.fi}">

  <meta property="og:type" content="website">
  <meta property="og:url" content="${canonicalUrl}">
  <meta property="og:title" content="${escapeAttr(i18n.pageTitle)}">
  <meta property="og:description" content="${escapeAttr(i18n.metaDesc)}">
  <meta property="og:image" content="${BASE_URL}/images/clinic-about.jpg">
  <meta property="og:locale" content="${i18n.ogLocale}">
  <meta property="og:site_name" content="${i18n.brandName}">

  <script type="application/ld+json">${JSON.stringify(jsonLd, null, 2)}</script>
  <script type="application/ld+json">${JSON.stringify(breadcrumbLd(lang, i18n.h1, canonicalUrl), null, 2)}</script>

  <link rel="preload" as="image" href="${assetPrefix}images/logo.png">
  <link rel="stylesheet" href="${assetPrefix}css/style.css${CSS_Q}">
  <link rel="icon" type="image/png" href="${assetPrefix}images/favicon-icon.png">
</head>
<body class="article-page">

  <a href="#main-content" class="skip-link">${escapeHtml(i18n.skipLink)}</a>

  <header class="header">
    <div class="container">
      <a href="${homeUrl}" class="logo">
        <div class="logo-icon"><img src="${assetPrefix}images/logo.png" alt="${i18n.brandName}" width="240" height="240"></div>
        <span class="logo-text">${i18n.brandName}</span>
      </a>
    </div>
  </header>

  <main id="main-content">
    <article class="article-page">
      <div class="container">
        <div class="page-back-wrapper">
          <a href="${homeUrl}" class="page-back-link">${escapeHtml(i18n.backToHome.replace(/^← /, ''))}</a>
        </div>

        <section class="reviews-hero">
          <h1>${escapeHtml(i18n.h1)}</h1>
          <div class="reviews-aggregate">
            <div class="reviews-aggregate-rating">
              <span class="reviews-aggregate-score">${ratingDisplay}</span>
              ${starBarHtml}
            </div>
            <div class="reviews-aggregate-meta">
              ${GOOGLE_TOTAL_REVIEWS} ${escapeHtml(i18n.reviewsOnGoogle)}
            </div>
            <div class="reviews-aggregate-meta reviews-aggregate-meta--secondary">
              ${escapeHtml(i18n.reviewsOnFacebook)}
            </div>
            <a class="reviews-aggregate-cta" href="${googleReviewsUrl}" target="_blank" rel="noopener">${escapeHtml(i18n.ctaReadAll)} →</a>
          </div>
        </section>

        <p class="reviews-featured-note">${escapeHtml(i18n.featuredNote)}</p>

        <section class="reviews-grid">
${reviewCards}
        </section>

        <section class="reviews-cta-block">
          <h2>${escapeHtml(i18n.ctaHeading)}</h2>
          <p>${escapeHtml(i18n.ctaText)}</p>
          <div class="reviews-cta-buttons">
            <a class="btn btn-primary" href="${googleReviewsUrl}" target="_blank" rel="noopener">${escapeHtml(i18n.ctaReadAll)}</a>
          </div>
          <p style="margin-top: 1.5rem; font-size: 0.85rem; color: var(--color-text-muted); max-width: 540px; margin-left: auto; margin-right: auto;">${escapeHtml(i18n.footnote)}</p>
        </section>
      </div>
    </article>
  </main>

  <footer class="footer">
    <div class="container">
      <div class="footer-bottom">
        <span>&copy; 2026 Eläinklinikka Saari Oy &middot; Y-tunnus: 0708667-9</span>
        <a href="${PRIVACY_HREF[lang] || PRIVACY_HREF.fi}">${escapeHtml(PRIVACY_LABEL[lang] || PRIVACY_LABEL.fi)}</a>
      </div>
    </div>
  </footer>

  <script src="${assetPrefix}js/main.js${ASSET_Q}" defer></script>
${renderCookieBanner(lang)}
</body>
</html>`;
}

// ──────────────────────────────────────────────
// 9y. Generate Booking page (/ajanvaraus/ /sv/tidsbokning/ /en/book-appointment/)
// ──────────────────────────────────────────────
// "Good to know" section under the booking buttons (added 21-11-2026; EN master approved
// by Assaf, FI/SV native writer + critic). Card text is HTML; href="@pricelist" becomes the
// language's price-list drop-in anchor. Phone numbers and "10 %" get no-break spaces.
// Heading reuses .booking-hero/.booking-subtitle; cards .booking-info-grid/.booking-info-card.
function renderBookingInfo(info, lang) {
  const keep = (t) => t
    .replace(/(\d) %/g, '$1&nbsp;%')
    .replace(/(\(0\d\)|0600) (\d{3}) (\d{3,4})/g, '$1&nbsp;$2&nbsp;$3');
  const cards = info.cards.map((c) => `            <div class="booking-info-card">
              <h3>${escapeHtml(c.h)}</h3>
              <p>${keep(c.p).replace(/href="@pricelist"/g, `href="${PRICES_URLS[lang]}#drop-in"`)}</p>
            </div>`).join('\n');
  return `
        <section class="booking-info" aria-labelledby="booking-info-title">
          <div class="booking-hero">
            <h2 class="booking-subtitle" id="booking-info-title">${escapeHtml(info.divider)}</h2>
          </div>
          <div class="booking-info-grid">
${cards}
          </div>
        </section>`;
}

