// ──────────────────────────────────────────────
// Utility functions
// ──────────────────────────────────────────────
// Two-step breadcrumb (home > this page) for pages that sit directly under the home page.
function breadcrumbLd(lang, name, url) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: ({ sv: 'Startsidan', en: 'Home' })[lang] || 'Etusivu', item: BASE_URL + (({ sv: '/sv/', en: '/en/' })[lang] || '/') },
      { '@type': 'ListItem', position: 2, name, item: url },
    ],
  };
}

function stripTags(str) {
  return String(str || '').replace(/<[^>]*>/g, '');
}

function escapeHtml(str) {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Write a generated file, but if the existing file differs ONLY in build-stamped
// dates (dateModified / lastReviewed / sitemap lastmod), keep it untouched.
// This keeps rebuild dates honest: a page's dateModified only moves when its
// content actually changes, and `git status` stays clean after a no-op rebuild.
function normalizeVolatileDates(s) {
  return s
    .replace(/("(?:dateModified|lastReviewed)":\s*")\d{4}-\d{2}-\d{2}(")/g, '$1DATE$2')
    .replace(/(<lastmod>)\d{4}-\d{2}-\d{2}(<\/lastmod>)/g, '$1DATE$2');
}
// Counts pages actually rewritten this run. The sitemap needs it: its own diff
// is frequently date-only (so the guard above would skip it) even when real page
// content changed, which would leave <lastmod> stale while the pages' own
// dateModified moved forward — search engines see the sitemap claiming a page is
// older than the page says it is. See writeSitemap below.
let pagesWritten = 0;
// Absolute paths of the pages rewritten this run (see writeSitemap).
const writtenFiles = new Set();
// Pages that carry OG tags but no twitter:* tags get twitter tags copied from
// their own OG title/description/image, placed right after the last og: meta.
// (X falls back poorly without twitter:card.) Hand pages got the same insert
// once by script on 08-11-2026, so a rebuild stays a no-op.
function addTwitterTags(html) {
  if (!/property="og:title"/.test(html) || /name="twitter:/.test(html)) return html;
  const og = (k) => { const m = html.match(new RegExp(`<meta property="og:${k}" content="([^"]*)">`)); return m ? m[1] : null; };
  const title = og('title'), desc = og('description'), image = og('image');
  const lines = [...html.matchAll(/^([ \t]*)<meta property="og:[^"]+" content="[^"]*">[ \t]*$/gm)];
  if (!title || !lines.length) return html;
  const last = lines[lines.length - 1], indent = last[1];
  const tags = [`${indent}<meta name="twitter:card" content="summary_large_image">`,
    `${indent}<meta name="twitter:title" content="${title}">`];
  if (desc) tags.push(`${indent}<meta name="twitter:description" content="${desc}">`);
  if (image) tags.push(`${indent}<meta name="twitter:image" content="${image}">`);
  const at = last.index + last[0].length;
  return html.slice(0, at) + '\n' + tags.join('\n') + html.slice(at);
}

function writeGenerated(file, content) {
  if (file.endsWith('.html')) content = addTwitterTags(content);
  try {
    const existing = fs.readFileSync(file, 'utf-8');
    if (normalizeVolatileDates(existing) === normalizeVolatileDates(content)) return false;
  } catch (e) { /* new file */ }
  fs.writeFileSync(file, content, 'utf-8');
  pagesWritten++;
  writtenFiles.add(path.resolve(file));
  return true;
}

// Write the sitemap. generateSitemap() stamps today's date on every URL, so the
// dates are merged here: a URL keeps the <lastmod> it already has in sitemap.xml
// and moves to today only when its own page file was rewritten in this run, or
// when the URL is new. (Until 10-11-2026 one rewritten page re-stamped all 227
// URLs, which is how the 09-11 consent-banner commit dated the whole site.)
// Hand-written pages are never rewritten by this build: when you change one by
// hand, set its <lastmod> in sitemap.xml by hand too.
function sitemapLocToFile(loc) {
  let p = decodeURI(loc.replace(BASE_URL, ''));
  if (p === '' || p.endsWith('/')) p += 'index.html';
  return path.resolve(ROOT, '.' + (p.startsWith('/') ? p : '/' + p));
}
const SITEMAP_ENTRY = /(<url>\s*<loc>)([^<]+)(<\/loc>\s*<lastmod>)(\d{4}-\d{2}-\d{2})(<\/lastmod>)/g;
function mergeSitemapLastmod(existing, content) {
  const kept = new Map();
  for (const m of existing.matchAll(SITEMAP_ENTRY)) kept.set(m[2], m[4]);
  return content.replace(SITEMAP_ENTRY, (all, a, loc, b, date, c) => {
    const old = kept.get(loc);
    if (!old || writtenFiles.has(sitemapLocToFile(loc))) return all;
    return a + loc + b + old + c;
  });
}
function writeSitemap(file, content) {
  let existing = null;
  try { existing = fs.readFileSync(file, 'utf-8'); } catch (e) { /* first build */ }
  if (existing !== null) content = mergeSitemapLastmod(existing, content);
  if (existing === content) return false;
  fs.writeFileSync(file, content, 'utf-8');
  return true;
}

// Wrap the clinic and emergency phone numbers in tel: links in visible HTML.
// Numbers already inside an <a>…</a> are left alone, so existing links and
// CTA buttons never get double-wrapped. Apply only to rendered HTML, never to
// JSON-LD schema strings (those must stay plain text).
const PHONE_PATTERNS = [
  { re: /\(06\) 321 7300/g, tel: '+35863217300' },
  { re: /\b06 321 7300/g, tel: '+35863217300' },
  { re: /\b0600 399 299/g, tel: '+358600399299' },
];
function linkifyPhones(html) {
  return html.split(/(<a\b[\s\S]*?<\/a>)/).map((part, i) => {
    if (i % 2 === 1) return part; // inside an existing anchor
    return PHONE_PATTERNS.reduce(
      (s, p) => s.replace(p.re, (m) => `<a href="tel:${p.tel}">${m}</a>`),
      part
    );
  }).join('');
}

// Footer quicklink targets shared by every page footer.
const ARTICLES_FOOTER_URLS = { fi: '/artikkelit/', sv: '/sv/artiklar/', en: '/en/articles/' };
const REVIEWS_URLS = { fi: '/arvostelut/', sv: '/sv/omdomen/', en: '/en/reviews/' };
const REVIEWS_LABELS = { fi: 'Arvostelut', sv: 'Omdömen', en: 'Reviews' };

function getArticlesUrl(lang) {
  // Root-relative on purpose: the footer links the same page root-relatively, and an
  // identical link text pointing at "two" URLs (absolute vs relative) trips a11y checks.
  if (lang === 'sv') return '/sv/artiklar/';
  if (lang === 'en') return '/en/articles/';
  return '/artikkelit/';
}

// Canonical nav labels used in every page's header (single source of truth).
const NAV_LABELS = {
  fi: { about: 'Klinikka', services: 'Palvelut', team: 'Henkilökunta', catfriendly: 'Cat Friendly', prices: 'Hinnasto', wildlife: 'Wildlife', contact: 'Yhteystiedot', articles: 'Artikkelit', book: 'Varaa aika' },
  sv: { about: 'Kliniken', services: 'Tjänster', team: 'Personal', catfriendly: 'Cat Friendly', prices: 'Prislista', wildlife: 'Wildlife', contact: 'Kontakt', articles: 'Artiklar', book: 'Boka tid' },
  en: { about: 'Clinic', services: 'Services', team: 'Staff', catfriendly: 'Cat Friendly', prices: 'Prices', wildlife: 'Wildlife', contact: 'Contact', articles: 'Articles', book: 'Book Now' }
};

// Full nav matching index.html — used on every non-homepage page so the header is identical everywhere.
// Article/service/static pages use <a> for the lang toggle (each lang is a separate URL); homepage uses <button> + JS.
function renderHeaderNav({ lang, homeUrl, articlesUrl, fiUrl, svUrl, enUrl }) {
  const nav = NAV_LABELS[lang] || NAV_LABELS.fi;
  const pricesUrl = PRICES_URLS[lang] || PRICES_URLS.fi;
  const bookingUrl = 'https://my.provet.com/elainklinikka-saari';
  return `      <nav class="nav">
        <div class="nav-links">
          <a href="${homeUrl}#about">${escapeHtml(nav.about)}</a>
          <a href="${homeUrl}#services">${escapeHtml(nav.services)}</a>
          <a href="${lang === 'fi' ? '/henkilokunta/' : `${homeUrl}#team`}">${escapeHtml(nav.team)}</a>
          <a href="${pricesUrl}">${escapeHtml(nav.prices)}</a>
          <a href="${homeUrl}#wildlife">${escapeHtml(nav.wildlife)}</a>
          <a href="${homeUrl}#contact">${escapeHtml(nav.contact)}</a>
          <a href="${articlesUrl}">${escapeHtml(nav.articles)}</a>
          <a href="${SHOP_URLS[lang] || SHOP_URLS.fi}" class="nav-shop">${SHOP_CART_SVG}<span>${escapeHtml(SHOP_LABELS[lang] || SHOP_LABELS.fi)}</span></a>
          <a href="${bookingUrl}" rel="noopener" class="btn btn-cta mobile-cta" onclick="fbq('track','Schedule');">${escapeHtml(nav.book)}</a>
        </div>

        <div class="nav-actions">
          <div class="lang-toggle">
            <a href="${fiUrl}" class="${lang === 'fi' ? 'active' : ''}"${lang === 'fi' ? ' aria-current="page"' : ''}>FI</a>
            <a href="${svUrl}" class="${lang === 'sv' ? 'active' : ''}"${lang === 'sv' ? ' aria-current="page"' : ''}>SV</a>
            <a href="${enUrl}" class="${lang === 'en' ? 'active' : ''}"${lang === 'en' ? ' aria-current="page"' : ''}>EN</a>
          </div>
          <a href="${bookingUrl}" rel="noopener" class="btn btn-cta btn-sm desktop-only" onclick="fbq('track','Schedule');">${escapeHtml(nav.book)}</a>
        </div>

        <button class="mobile-menu-btn" aria-label="Menu">
          <span></span>
          <span></span>
          <span></span>
        </button>
      </nav>`;
}

function escapeAttr(str) {
  return str.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ──────────────────────────────────────────────
// Main
// ──────────────────────────────────────────────
function main() {
  console.log('Building article pages...\n');

  // Load translations
  console.log('Loading translations from js/main.js...');
  const translations = loadTranslations();
  const translationKeys = Object.keys(translations);
  console.log(`  Found ${translationKeys.length} translation keys`);

  // Read index.html for special content
  console.log('Reading index.html for special article content...');
  const indexHtml = fs.readFileSync(INDEX_PATH, 'utf-8');
  const specialContent = extractSpecialContent(indexHtml);

  // Ensure articles directory exists
  if (!fs.existsSync(ARTICLES_DIR)) {
    fs.mkdirSync(ARTICLES_DIR, { recursive: true });
  }

  // Generate each article page (FI, SV, EN)
  let count = 0;
  const svDir = path.join(ROOT, 'sv', 'artiklar');
  const enDir = path.join(ROOT, 'en', 'articles');
  if (!fs.existsSync(svDir)) fs.mkdirSync(svDir, { recursive: true });
  if (!fs.existsSync(enDir)) fs.mkdirSync(enDir, { recursive: true });

  for (const article of articles) {
    if (article.skipBuild) {
      console.log(`  SKIP ${article.slug} (rendered files preserved — see article.skipBuild)`);
      continue;
    }
    // Finnish
    const titleFi = translations[article.titleKey]?.fi || article.slug;
    const htmlFi = generateArticlePage(article, translations, specialContent, 'fi');
    writeGenerated(path.join(ARTICLES_DIR, `${article.slug}.html`), htmlFi);
    count++;
    console.log(`  [${count}/${articles.length}] ${article.slug}.html - ${titleFi.substring(0, 60)}...`);

    // Swedish
    const htmlSv = generateArticlePage(article, translations, specialContent, 'sv');
    const svSlug = articleSlug(article, 'sv');
    writeGenerated(path.join(svDir, `${svSlug}.html`), htmlSv);
    if (svSlug !== article.slug) {
      const oldSvPath = path.join(svDir, `${article.slug}.html`);
      const newSvUrl = `${BASE_URL}/sv/artiklar/${svSlug}.html`;
      fs.writeFileSync(oldSvPath, generateRedirectStub(newSvUrl), 'utf-8');
    }

    // English
    const htmlEn = generateArticlePage(article, translations, specialContent, 'en');
    const enSlug = articleSlug(article, 'en');
    writeGenerated(path.join(enDir, `${enSlug}.html`), htmlEn);
    if (enSlug !== article.slug) {
      const oldEnPath = path.join(enDir, `${article.slug}.html`);
      const newEnUrl = `${BASE_URL}/en/articles/${enSlug}.html`;
      fs.writeFileSync(oldEnPath, generateRedirectStub(newEnUrl), 'utf-8');
    }
  }

  // Generate service landing pages (FI, SV, EN)
  console.log('\nBuilding service pages...');
  for (const service of servicePages) {
    if (service.skipBuild) {
      console.log(`  SKIP ${service.slug} (rendered files preserved — see service.skipBuild)`);
      continue;
    }
    // Finnish
    const serviceDir = path.join(ROOT, 'palvelut', service.slug);
    if (!fs.existsSync(serviceDir)) {
      fs.mkdirSync(serviceDir, { recursive: true });
    }
    const htmlFi = fiSvDashes(generateServicePage(service, translations, 'fi'), 'fi');
    writeGenerated(path.join(serviceDir, 'index.html'), htmlFi);
    console.log(`  palvelut/${service.slug}/index.html - ${service.h1}`);

    // Swedish
    const svDir = path.join(ROOT, 'sv', 'tjanster', service.slugSv);
    if (!fs.existsSync(svDir)) {
      fs.mkdirSync(svDir, { recursive: true });
    }
    const htmlSv = fiSvDashes(generateServicePage(service, translations, 'sv'), 'sv');
    writeGenerated(path.join(svDir, 'index.html'), htmlSv);
    console.log(`  sv/tjanster/${service.slugSv}/index.html - ${service.sv.h1}`);

    // English
    const enDir = path.join(ROOT, 'en', 'services', service.slugEn);
    if (!fs.existsSync(enDir)) {
      fs.mkdirSync(enDir, { recursive: true });
    }
    const htmlEn = generateServicePage(service, translations, 'en');
    writeGenerated(path.join(enDir, 'index.html'), htmlEn);
    console.log(`  en/services/${service.slugEn}/index.html - ${service.en.h1}`);
  }

  // Generate trilingual article index pages (FI: /artikkelit/, SV: /sv/artiklar/, EN: /en/articles/)
  console.log('\nBuilding article index pages...');
  const indexTargets = [
    { lang: 'fi', dir: path.join(ROOT, 'artikkelit'), label: 'artikkelit/index.html' },
    { lang: 'sv', dir: path.join(ROOT, 'sv', 'artiklar'), label: 'sv/artiklar/index.html' },
    { lang: 'en', dir: path.join(ROOT, 'en', 'articles'), label: 'en/articles/index.html' },
  ];
  for (const target of indexTargets) {
    if (!fs.existsSync(target.dir)) fs.mkdirSync(target.dir, { recursive: true });
    const indexPage = generateArticleIndex(translations, target.lang);
    writeGenerated(path.join(target.dir, 'index.html'), indexPage);
    console.log(`  Generated ${target.label}`);
  }

  // Generate about page
  console.log('\nBuilding about page...');
  const aboutDir = path.join(ROOT, 'meista');
  if (!fs.existsSync(aboutDir)) {
    fs.mkdirSync(aboutDir, { recursive: true });
  }
  const aboutPage = fiSvDashes(generateAboutPage(), 'fi');
  writeGenerated(path.join(aboutDir, 'index.html'), aboutPage);
  console.log('  Generated meista/index.html');

  // Generate contact page
  console.log('Building contact page...');
  const contactDir = path.join(ROOT, 'yhteystiedot');
  if (!fs.existsSync(contactDir)) {
    fs.mkdirSync(contactDir, { recursive: true });
  }
  const contactPage = fiSvDashes(generateContactPage(), 'fi');
  writeGenerated(path.join(contactDir, 'index.html'), contactPage);
  console.log('  Generated yhteystiedot/index.html');

  // Generate privacy policy page
  console.log('\nBuilding privacy policy page...');
  const privacyDir = path.join(ROOT, 'tietosuoja');
  if (!fs.existsSync(privacyDir)) {
    fs.mkdirSync(privacyDir, { recursive: true });
  }
  // Since 09-11-2026 the privacy pages (FI/SV/EN) are built by tools/consent/build_privacy.py from
  // docs/compliance-2026-11/*_final.json; generatePrivacyPage() below is the retired old version.
  console.log('  Skipped: tietosuoja/ is built by tools/consent/build_privacy.py');

  // Generate reviews pages (FI, SV, EN)
  console.log('\nBuilding reviews pages...');
  const reviewsTargets = [
    { lang: 'fi', dir: path.join(ROOT, 'arvostelut'), label: 'arvostelut/index.html' },
    { lang: 'sv', dir: path.join(ROOT, 'sv', 'omdomen'), label: 'sv/omdomen/index.html' },
    { lang: 'en', dir: path.join(ROOT, 'en', 'reviews'), label: 'en/reviews/index.html' },
  ];
  for (const t of reviewsTargets) {
    if (!fs.existsSync(t.dir)) fs.mkdirSync(t.dir, { recursive: true });
    const html = fiSvDashes(generateReviewsPage(t.lang), t.lang);
    writeGenerated(path.join(t.dir, 'index.html'), html);
    console.log(`  Generated ${t.label}`);
  }

  // Generate booking pages (FI, SV, EN)
  console.log('\nBuilding booking pages...');
  const bookingTargets = [
    { lang: 'fi', dir: path.join(ROOT, 'ajanvaraus'), label: 'ajanvaraus/index.html' },
    { lang: 'sv', dir: path.join(ROOT, 'sv', 'tidsbokning'), label: 'sv/tidsbokning/index.html' },
    { lang: 'en', dir: path.join(ROOT, 'en', 'book-appointment'), label: 'en/book-appointment/index.html' },
  ];
  for (const t of bookingTargets) {
    if (!fs.existsSync(t.dir)) fs.mkdirSync(t.dir, { recursive: true });
    const html = generateBookingPage(t.lang);
    writeGenerated(path.join(t.dir, 'index.html'), html);
    console.log(`  Generated ${t.label}`);
  }

  // Generate sitemap
  console.log('\nGenerating sitemap.xml...');
  const sitemap = generateSitemap();
  writeSitemap(SITEMAP_PATH, sitemap);
  console.log(`  Sitemap updated with ${articles.length + servicePages.length + 3} URLs`);

  console.log(`\nDone! Generated ${count} article pages in articles/`);
}

main();
